def min_zero_array(nums: list[int], queries: list[list[int]]) -> int:
    n = len(nums)
    diff = [0] * (n + 1)
    capacity = 0          # total decrement available at the current index
    k = 0                 # number of queries applied so far
    for i in range(n):
        capacity += diff[i]
        while capacity < nums[i]:
            if k == len(queries):
                return -1
            l, r, val = queries[k]
            k += 1
            if r < i:
                continue              # only touched indices that are done
            if l <= i:
                capacity += val       # active right now
            else:
                diff[l] += val        # becomes active later
            diff[r + 1] -= val
    return k

