def remove_comments(source: list[str]) -> list[str]:
    result = []
    buffer = []
    in_block = False
    for line in source:
        i, n = 0, len(line)
        while i < n:
            two = line[i:i + 2]
            if in_block:
                if two == "*/":
                    in_block = False
                    i += 2
                else:
                    i += 1
            elif two == "/*":
                in_block = True
                i += 2
            elif two == "//":
                break                     # rest of the line is a comment
            else:
                buffer.append(line[i])
                i += 1
        # A line is finished only when no block comment is still open.
        if not in_block and buffer:
            result.append("".join(buffer))
            buffer = []
    return result

def leaf_similar(root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
    def leaves(root):
        out, stack = [], [root] if root else []
        while stack:
            node = stack.pop()
            if node.left is None and node.right is None:
                out.append(node.val)
                continue
            # Right first so the left subtree is explored first.
            if node.right:
                stack.append(node.right)
            if node.left:
                stack.append(node.left)
        return out

    return leaves(root1) == leaves(root2)

def trim_bst(root: Optional[TreeNode], low: int, high: int) -> Optional[TreeNode]:
    if root is None:
        return None
    if root.val < low:
        # Everything on the left is smaller still: only the right side can survive.
        return trim_bst(root.right, low, high)
    if root.val > high:
        return trim_bst(root.left, low, high)
    root.left = trim_bst(root.left, low, high)
    root.right = trim_bst(root.right, low, high)
    return root

