def min_time_to_reach(moveTime: list[list[int]]) -> int:
    n, m = len(moveTime), len(moveTime[0])
    INF = float("inf")
    best = [[INF] * m for _ in range(n)]
    best[0][0] = 0
    heap = [(0, 0, 0)]
    while heap:
        t, r, c = heapq.heappop(heap)
        if t > best[r][c]:
            continue  # stale heap entry
        if r == n - 1 and c == m - 1:
            return t
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < m:
                arrive = max(t, moveTime[nr][nc]) + 1  # wait if needed, then move
                if arrive < best[nr][nc]:
                    best[nr][nc] = arrive
                    heapq.heappush(heap, (arrive, nr, nc))
    return best[n - 1][m - 1]

