    m, n = len(grid), len(grid[0])
    if grid[0][1] > 1 and grid[1][0] > 1:
        return -1  # cannot make the first move, and staying is not allowed
    INF = float("inf")
    best = [INF] * (m * n)
    best[0] = 0
    heap = [(0, 0)]
    target = m * n - 1
    while heap:
        t, cell = heapq.heappop(heap)
        if t > best[cell]:
            continue
