                    heapq.heappush(heap, (arrive, nxt))
    return -1

def max_partition_factor(points: list[list[int]]) -> int:
    n = len(points)
    if n == 2:
        return 0
    pairs = []
    for i in range(n):
        xi, yi = points[i]
        for j in range(i + 1, n):
            pairs.append((abs(xi - points[j][0]) + abs(yi - points[j][1]), i, j))
    pairs.sort()

    parent = list(range(n))
    parity = [0] * n  # parity of a node relative to its parent

    def find(x):
        # returns (root, parity of x relative to root), compressing the path
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        root, acc = x, 0
        for node in reversed(path):
            acc ^= parity[node]
            parity[node] = acc
            parent[node] = root
        return root

    for dist, i, j in pairs:
        ri, rj = find(i), find(j)
        pi = parity[i] if i != ri else 0
        pj = parity[j] if j != rj else 0
        if ri == rj:
            if pi == pj:
                return dist  # i and j are forced into the same group
        else:
            parent[ri] = rj
            parity[ri] = pi ^ pj ^ 1  # place i and j on opposite sides
    return 0

