def sort_items(n: int, m: int, group: list[int], beforeItems: list[list[int]]) -> list[int]:
    group = list(group)
    for i in range(n):
        if group[i] == -1:
            group[i] = m  # fresh group for each ungrouped item
            m += 1

    item_adj = [[] for _ in range(n)]
    item_in = [0] * n
    group_adj = [[] for _ in range(m)]
    group_in = [0] * m
    for i in range(n):
        for b in beforeItems[i]:
            item_adj[b].append(i)
            item_in[i] += 1
            if group[b] != group[i]:
                group_adj[group[b]].append(group[i])
                group_in[group[i]] += 1

    def topo(adj, indeg):
        indeg = indeg[:]
        queue = deque(v for v in range(len(adj)) if indeg[v] == 0)
        order = []
        while queue:
            v = queue.popleft()
            order.append(v)
            for w in adj[v]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    queue.append(w)
        return order if len(order) == len(adj) else None

    item_order = topo(item_adj, item_in)
    group_order = topo(group_adj, group_in)
    if item_order is None or group_order is None:
        return []

    members = [[] for _ in range(m)]
    for item in item_order:
        members[group[item]].append(item)
    result = []
    for g in group_order:
        result.extend(members[g])
    return result

