def continuous_subarrays(nums: list[int]) -> int:
    maxq, minq = deque(), deque()  # indices with decreasing / increasing values
    left = 0
    total = 0
    for right, x in enumerate(nums):
        while maxq and nums[maxq[-1]] <= x:
            maxq.pop()
        maxq.append(right)
        while minq and nums[minq[-1]] >= x:
            minq.pop()
        minq.append(right)
        # shrink until max - min <= 2
        while nums[maxq[0]] - nums[minq[0]] > 2:
            left += 1
            if maxq[0] < left:
                maxq.popleft()
            if minq[0] < left:
                minq.popleft()
        total += right - left + 1
    return total

