def largest_palindrome(n: int) -> int:
    if n == 1:
        return 9                        # 3 * 3, or 1 * 9
    base = 10 ** n
    # Factors are base - x and base - y. With z = x + y the product has upper
    # half base - z and lower half x * y, which must be the reversed upper half.
    for z in range(2, 9 * 10 ** (n - 1)):
        upper = base - z
        lower = int(str(upper)[::-1])
        disc = z * z - 4 * lower        # x and y are roots of t^2 - z t + lower
        if disc < 0:
            continue
        root = math.isqrt(disc)
        if root * root == disc:
            return (upper * base + lower) % 1337
    return -1

def postorder_traversal(root: Optional[TreeNode]) -> list[int]:
    if root is None:
        return []
    out = []
    stack = [root]
    # Collect node, right, left; the reverse of that order is postorder.
    while stack:
        node = stack.pop()
        out.append(node.val)
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    out.reverse()
    return out

