def can_i_win(max_choosable_integer: int, desired_total: int) -> bool:
    n = max_choosable_integer
    if desired_total <= 0:
        return True
    if n * (n + 1) // 2 < desired_total:
        return False
    memo = {}

    def wins(mask: int, remaining: int) -> bool:
        """True if the player to move wins; bit i - 1 of mask marks number i as used."""
        if mask in memo:
            return memo[mask]
        result = False
        bit = 1
        for num in range(1, n + 1):
            if not mask & bit:
                if num >= remaining or not wins(mask | bit, remaining - num):
                    result = True
                    break
            bit <<= 1
        memo[mask] = result
        return result

    return wins(0, desired_total)

def sort_transformed_array(nums: list[int], a: int, b: int, c: int) -> list[int]:
    def f(x: int) -> int:
        return a * x * x + b * x + c

    n = len(nums)
    out = [0] * n
    lo, hi = 0, n - 1
    if a >= 0:
        # The largest remaining value is at one of the ends: fill from the back.
        pos = n - 1
        while lo <= hi:
            left, right = f(nums[lo]), f(nums[hi])
            if left >= right:
                out[pos] = left
                lo += 1
            else:
                out[pos] = right
                hi -= 1
            pos -= 1
    else:
        # The smallest remaining value is at one of the ends: fill from the front.
        pos = 0
        while lo <= hi:
            left, right = f(nums[lo]), f(nums[hi])
            if left <= right:
                out[pos] = left
                lo += 1
            else:
                out[pos] = right
                hi -= 1
            pos += 1
    return out

