            num = heapq.heappop(self.heap)
            self.in_heap.discard(num)
            return num
        self.next_new += 1
        return self.next_new - 1

    def addBack(self, num: int) -> None:
        if num < self.next_new and num not in self.in_heap:
            heapq.heappush(self.heap, num)
            self.in_heap.add(num)

