def find_max_val(n: int, restrictions: list[list[int]], diff: list[int]) -> int:
    INF = 1 << 60                     # larger than any reachable value
    lim = [INF] * n
    lim[0] = 0
    for idx, cap in restrictions:
        lim[idx] = min(lim[idx], cap)
    # Spread every upper bound to the right, then to the left.
    for i in range(n - 1):
        if lim[i] + diff[i] < lim[i + 1]:
            lim[i + 1] = lim[i] + diff[i]
    for i in range(n - 2, -1, -1):
        if lim[i + 1] + diff[i] < lim[i]:
            lim[i] = lim[i + 1] + diff[i]
    return max(lim)

