    def edit(self, taskId: int, newPriority: int) -> None:
        user_id, _ = self.info[taskId]
        self.info[taskId] = (user_id, newPriority)
        heapq.heappush(self.heap, (-newPriority, -taskId))

    def rmv(self, taskId: int) -> None:
        del self.info[taskId]

    def execTop(self) -> int:
        while self.heap:
            neg_p, neg_t = heapq.heappop(self.heap)
            task_id = -neg_t
            live = self.info.get(task_id)
            # Skip entries for removed tasks or outdated priorities.
            if live is not None and live[1] == -neg_p:
                del self.info[task_id]
                return live[0]
        return -1

