def is_valid(code: str) -> bool:
    stack = []
    i, n = 0, len(code)
    while i < n:
        if i > 0 and not stack:
            return False                    # text outside the single outer tag
        if code.startswith("<![CDATA[", i):
            if not stack:
                return False                # CDATA must be inside a tag
            end = code.find("]]>", i + 9)
            if end < 0:
                return False
            i = end + 3
        elif code.startswith("</", i):
            end = code.find(">", i + 2)
            if end < 0:
                return False
            name = code[i + 2:end]
            if not stack or stack[-1] != name:
                return False
            stack.pop()
            i = end + 1
        elif code[i] == "<":
            end = code.find(">", i + 1)
            if end < 0:
                return False
            name = code[i + 1:end]
            if not (1 <= len(name) <= 9 and all("A" <= ch <= "Z" for ch in name)):
                return False
            stack.append(name)
            i = end + 1
        else:
            if not stack:
                return False                # plain text before any tag
            i += 1
    return not stack

def smallest_repunit_div_by_k(k: int) -> int:
    if k % 2 == 0 or k % 5 == 0:
        return -1                      # a number of all 1s ends in 1
    remainder = 0
    for length in range(1, k + 1):
        remainder = (remainder * 10 + 1) % k
        if remainder == 0:
            return length
    return -1

